func setIngressDNSHost(config *config.Config, workspace string, workload string) string {
	var dnsName string
	switch workload {
	case "ollama":
		dnsName = fmt.Sprintf("%s-api.%s", workspace, config.DefaultDomain)
	case "openwebui":
		dnsName = fmt.Sprintf("%s.%s", workspace, config.DefaultDomain)
	}
	return dnsName
